-- Esquema del recorte CU28. Compatible con PostgreSQL y H2 2.x.
CREATE TABLE IF NOT EXISTS cm (id_cm INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, codigo VARCHAR(30) UNIQUE NOT NULL, nombre VARCHAR(150) UNIQUE NOT NULL, direccion VARCHAR(200), email VARCHAR(150), telefono VARCHAR(50));
CREATE TABLE IF NOT EXISTS estado (id_estado INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre VARCHAR(100) NOT NULL, descripcion VARCHAR(200), ambito VARCHAR(30) NOT NULL, UNIQUE(nombre, ambito));
CREATE TABLE IF NOT EXISTS empleado (id_empleado INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre VARCHAR(80), apellido VARCHAR(80), email VARCHAR(150), id_cm INTEGER NOT NULL REFERENCES cm(id_cm));
CREATE TABLE IF NOT EXISTS usuario (id_usuario INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre VARCHAR(80) UNIQUE NOT NULL, contrasena VARCHAR(200), id_empleado INTEGER NOT NULL REFERENCES empleado(id_empleado));
CREATE TABLE IF NOT EXISTS sesion (id_sesion INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, fecha_hora_inicio TIMESTAMP NOT NULL, fecha_hora_fin TIMESTAMP, id_usuario INTEGER NOT NULL REFERENCES usuario(id_usuario));
CREATE TABLE IF NOT EXISTS tipo_documentacion (id_tipo_doc INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre VARCHAR(100), descripcion VARCHAR(200));
CREATE TABLE IF NOT EXISTS documentacion (id_documentacion INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, numero INTEGER UNIQUE NOT NULL, asunto VARCHAR(300) NOT NULL, fecha_pase DATE NOT NULL, id_tipo_doc INTEGER NOT NULL REFERENCES tipo_documentacion(id_tipo_doc), id_cm_origen INTEGER NOT NULL REFERENCES cm(id_cm));
CREATE TABLE IF NOT EXISTS bolsin (id_bolsin INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, numero_bolsin INTEGER UNIQUE NOT NULL, numero_precinto VARCHAR(100), fecha DATE NOT NULL, peso REAL, id_cm_origen INTEGER NOT NULL REFERENCES cm(id_cm), id_cm_destino INTEGER NOT NULL REFERENCES cm(id_cm));
CREATE TABLE IF NOT EXISTS remito (id_remito INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, numero INTEGER UNIQUE NOT NULL, fecha DATE NOT NULL, id_bolsin INTEGER REFERENCES bolsin(id_bolsin), id_estado INTEGER REFERENCES estado(id_estado), id_cm_origen INTEGER NOT NULL REFERENCES cm(id_cm), id_cm_destino INTEGER NOT NULL REFERENCES cm(id_cm));
CREATE TABLE IF NOT EXISTS detalle_remito (id_detalle_remito INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_remito INTEGER NOT NULL REFERENCES remito(id_remito), id_documentacion INTEGER NOT NULL REFERENCES documentacion(id_documentacion), area_cmc_destino VARCHAR(100), UNIQUE(id_remito, id_documentacion));
CREATE TABLE IF NOT EXISTS cambio_estado_bolsin (id_cambio_estado_bolsin INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_bolsin INTEGER NOT NULL REFERENCES bolsin(id_bolsin), id_estado INTEGER NOT NULL REFERENCES estado(id_estado), fecha_hora_inicio TIMESTAMP NOT NULL, fecha_hora_fin TIMESTAMP, id_empleado INTEGER REFERENCES empleado(id_empleado), CHECK(fecha_hora_fin IS NULL OR fecha_hora_fin >= fecha_hora_inicio));
CREATE TABLE IF NOT EXISTS cambio_estado_documentacion (id_cambio_estado_doc INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_documentacion INTEGER NOT NULL REFERENCES documentacion(id_documentacion), id_estado INTEGER NOT NULL REFERENCES estado(id_estado), fecha_hora_inicio TIMESTAMP NOT NULL, fecha_hora_fin TIMESTAMP, id_empleado INTEGER REFERENCES empleado(id_empleado), CHECK(fecha_hora_fin IS NULL OR fecha_hora_fin >= fecha_hora_inicio));
